import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.mRCPFc5l.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"WheelOS Docs","text":"面向 AI 的自动驾驶工程知识库","tagline":"让 AI 不只“知道概念”，还能判断方案是否被真实验证过。","actions":[{"theme":"brand","text":"从问题开始","link":"/knowledge/"},{"theme":"alt","text":"了解 WheelOS","link":"/about/wheelos"}]},"features":[{"title":"先定义问题","details":"按症状、约束、输入输出和验收指标组织内容，帮助 AI 进行故障定位和方案选择。","link":"/about/how-to-read"},{"title":"区分事实与推测","details":"每条知识明确证据等级、验证环境、版本和已知边界，不把“看起来合理”当成“已经可用”。","link":"/practice/"},{"title":"持续沉淀实践","details":"问题、实验、结果和失败方案都可以记录，形成可追溯的自动驾驶工程记忆。","link":"/practice/verified"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1787217884000}'),o={name:"index.md"};function r(n,e,s,d,h,p){return t(),l("div",null,[...e[0]||(e[0]=[i('<h2 id="这个文档解决什么问题" tabindex="-1">这个文档解决什么问题？ <a class="header-anchor" href="#这个文档解决什么问题" aria-label="Permalink to &quot;这个文档解决什么问题？&quot;">​</a></h2><p>自动驾驶系统横跨传感器、时间同步、坐标系、定位、感知、预测、规划、控制、底盘和工具链。单独的概念说明很难回答工程问题：</p><ul><li>为什么车辆在仿真中正常，实车却出现规划抖动？</li><li>多传感器数据的时间戳应该在哪里校正，如何证明校正有效？</li><li>一个方案是 WheelOS 已经实现的能力，还是仅仅是社区的设计建议？</li><li>当现象无法复现时，AI 应该先索取哪些日志和指标？</li></ul><p>本知识库的目标是让这些问题有<strong>可引用、可验证、可继续补充</strong>的答案。当前内容会明确标注哪些信息来自仓库、哪些是待补充的实践记录；没有证据时不会伪造结论。</p><p>本站必须遵守两条原则：<a href="/about/principles">对 AI 友好</a>和<a href="/about/principles">强验证</a>。如果没有可追溯实验，答案必须保持为“待验证”。</p><h2 id="给-ai-的使用方式" tabindex="-1">给 AI 的使用方式 <a class="header-anchor" href="#给-ai-的使用方式" aria-label="Permalink to &quot;给 AI 的使用方式&quot;">​</a></h2><ol><li>先阅读<a href="/about/how-to-read">如何阅读本知识库</a>，理解证据等级和回答边界。</li><li>按问题现象进入<a href="/knowledge/">自动驾驶问题库</a>，不要只按模块名搜索。</li><li>回答时引用具体页面，并同时说明适用条件、验证状态和缺失信息。</li><li>若仓库没有答案，输出“未知/待验证”，并按照页面中的最小复现信息提出下一步实验。</li></ol><p>机器读取入口：<a href="/llms.txt">llms.txt</a> · <a href="/llms-full.txt">完整机器读取索引</a></p>',8)])])}const f=a(o,[["render",r]]);export{_ as __pageData,f as default};
